{
"schemaVersion": "scene-document/v2",
"visualDecision": "scene",
"source": {
"question": "The time taken by a block of mass m to slide down from the highest point to the lowest point on a rough 45° incline is 50% more than on an identical smooth 45° incline. Find the coefficient of kinetic friction. Options: 3/4, 2/3, 5/9, 4/9.",
"representationTier": "qualitative_verified",
"nonMetric": true
},
"quantities": [
{"id": "g1", "symbol": "θ", "value": 45, "unit": "deg", "sourceText": "45° incline", "provenance": "given"},
{"id": "g2", "symbol": "t_r/t_s", "value": 1.5, "sourceText": "time on rough incline is 50% more than on smooth", "provenance": "given"}
],
"entities": [
{"id": "p_base", "kind": "point"},
{"id": "p_top", "kind": "point"},
{"id": "p_right", "kind": "point"},
{"id": "incline_plane", "kind": "segment", "role": "inclined plane"},
{"id": "ground_line", "kind": "segment", "role": "ground"},
{"id": "block_body", "kind": "rectangle", "role": "body"},
{"id": "weight_vec", "kind": "vector", "role": "weight"},
{"id": "normal_vec", "kind": "vector", "role": "normal"},
{"id": "friction_vec", "kind": "vector", "role": "friction"},
{"id": "angle_mark_theta", "kind": "angle_mark", "role": "incline angle"}
],
"constructions": [
{"id": "c1", "operator": "point", "inputs": {"x": 0, "y": 0, "coordinateSpace": "world"}, "outputs": ["p_base"]},
{"id": "c2", "operator": "point", "inputs": {"x": 0, "y": 4, "coordinateSpace": "world"}, "outputs": ["p_top"]},
{"id": "c3", "operator": "point", "inputs": {"x": 4, "y": 0, "coordinateSpace": "world"}, "outputs": ["p_right"]},
{"id": "c4", "operator": "segment", "inputs": {"start": "p_top", "end": "p_right"}, "outputs": ["incline_plane"]},
{"id": "c5", "operator": "segment", "inputs": {"start": "p_base", "end": "p_right"}, "outputs": ["ground_line"]},
{"id": "c6", "operator": "rectangle", "inputs": {"center": "p_top", "width": 0.8, "height": 0.8}, "outputs": ["block_body"]},
{"id": "c7", "operator": "vector", "inputs": {"start": "p_top", "direction": [0, -1], "length": 1.5}, "outputs": ["weight_vec"]},
{"id": "c8", "operator": "vector", "inputs": {"start": "p_top", "direction": [0.7071, 0.7071], "length": 1.2}, "outputs": ["normal_vec"]},
{"id": "c9", "operator": "vector", "inputs": {"start": "p_top", "direction": [-0.7071, 0.7071], "length": 0.8}, "outputs": ["friction_vec"]},
{"id": "c10", "operator": "angle_mark", "inputs": {"vertex": "p_right", "a": "p_base", "b": "p_top", "radius": 0.6}, "outputs": ["angle_mark_theta"]}
],
"relations": [
{"predicate": "on", "entities": ["p_top", "incline_plane"]},
{"predicate": "perpendicular", "entities": ["normal_vec", "incline_plane"]},
{"predicate": "angle_between", "entities": ["incline_plane", "ground_line"], "expected": {"value": 45, "unit": "degree"}}
],
"assertions": [
{"id": "a1", "predicate": "angle_between", "entities": ["incline_plane", "ground_line"], "expected": {"value": 45, "unit": "degree"}, "severity": "required"},
{"id": "a2", "predicate": "perpendicular", "entities": ["normal_vec", "incline_plane"], "expected": true, "severity": "required"},
{"id": "a3", "predicate": "on", "entities": ["p_top", "incline_plane"], "expected": true, "severity": "required"}
],
"annotations": [
{"id": "ann1", "kind": "label", "targetIds": ["angle_mark_theta"], "text": "θ = 45°"},
{"id": "ann2", "kind": "label", "targetIds": ["weight_vec"], "text": "mg"},
{"id": "ann3", "kind": "label", "targetIds": ["normal_vec"], "text": "N"},
{"id": "ann4", "kind": "label", "targetIds": ["friction_vec"], "text": "f_k"},
{"id": "ann5", "kind": "label", "targetIds": ["block_body"], "text": "m"},
{"id": "ann6", "kind": "narration", "targetIds": ["incline_plane"], "text": "Rough 45° incline: block slides from rest; friction acts up the slope opposing motion."}
],
"requiredEntityIds": ["incline_plane", "block_body", "weight_vec", "normal_vec", "friction_vec", "angle_mark_theta"],
"revealGroups": [
{"id": "rg1", "entityIds": ["p_base", "p_top", "p_right", "incline_plane", "ground_line", "block_body", "weight_vec", "normal_vec", "friction_vec", "angle_mark_theta"]}
],
"teachingTimeline": [
{"step": 1, "action": "reveal", "targetIds": ["rg1"], "narration": "A block of mass m rests at the top of a rough 45° incline. Forces: weight mg downward, normal N perpendicular to the plane, kinetic friction f_k up the slope."}
]
}

{
"schemaVersion": "scene-document/v2",
"visualDecision": "scene",
"source": {
"question": "exponential growth and decay",
"representationTier": "qualitative_verified",
"nonMetric": true
},
"quantities": [],
"entities": [
{"id": "ax", "kind": "axes", "role": "coordinate frame"},
{"id": "growthCurve", "kind": "polyline", "role": "growth curve", "label": "y = a(1 + r)^t"},
{"id": "decayCurve", "kind": "polyline", "role": "decay curve", "label": "y = a(1 - r)^t"},
{"id": "startPoint", "kind": "point", "role": "shared initial amount", "label": "(0, a)"}
],
"constructions": [
{"id": "c1", "operator": "axes", "inputs": {"xMin": 0, "xMax": 6, "yMin": 0, "yMax": 4}, "outputs": ["ax"]},
{"id": "c2", "operator": "function_curve", "inputs": {"expression": "1.5*pow(1.35,x)", "variable": "x", "xMin": 0, "xMax": 6, "samples": 120}, "outputs": ["growthCurve"]},
{"id": "c3", "operator": "function_curve", "inputs": {"expression": "1.5*pow(0.65,x)", "variable": "x", "xMin": 0, "xMax": 6, "samples": 120}, "outputs": ["decayCurve"]},
{"id": "c4", "operator": "curve_anchor", "inputs": {"curve": "growthCurve", "at": 0}, "outputs": ["startPoint"]}
],
"relations": [
{"on": ["startPoint", "growthCurve"]},
{"on": ["startPoint", "decayCurve"]}
],
"assertions": [
{"id": "a1", "predicate": "function_value", "entities": ["growthCurve"], "expected": {"x": 0, "y": 1.5}, "severity": "info"},
{"id": "a2", "predicate": "function_value", "entities": ["decayCurve"], "expected": {"x": 0, "y": 1.5}, "severity": "info"}
],
"annotations": [
{"id": "n1", "kind": "narration", "targetIds": ["growthCurve", "decayCurve"], "text": "Growth: y = a(1 + r)^t rises from a; decay: y = a(1 - r)^t falls from a. Both start at the initial amount a when t = 0.", "placementIntent": "above"}
],
"requiredEntityIds": ["ax", "growthCurve", "decayCurve", "startPoint"],
"revealGroups": [
{"id": "g1", "entityIds": ["ax", "growthCurve", "decayCurve", "startPoint"]}
],
"teachingTimeline": []
}
